var onb=[],statusCount={},subjPat={};
for(var i=1;i<rows.length;i++){var r=rows[i]||[];var firm=String(r[C.firm]||'').trim();
 var em=String(r[C.email]||'').split(/[,;]+/).map(function(x){return x.trim().toLowerCase();}).filter(function(x){return x.indexOf('@')>0;});
 if(!firm&&!em.length)continue;
 var st=String(r[C.status]||'').trim();statusCount[st||'(blank)']=(statusCount[st||'(blank)']||0)+1;
 var sj=String(r[C.subject]||'').trim();if(sj){var key=sj.replace(/for .*$/i,'for <X>');subjPat[key]=(subjPat[key]||0)+1;}
