var iD=ih.indexOf('do_not_contact');var iF=ih.indexOf('investor_name');if(iF<0)iF=ih.indexOf('firm');if(iF<0)iF=ih.indexOf('name');if(iF<0)iF=0;
var dnc=[];if(iD>=0){for(var a=1;a<irows.length;a++){var rr=irows[a]||[];var v=String(rr[iD]||'').trim().toLowerCase();if(v&&v!=='no'&&v!=='false'&&v!=='0')dnc.push(String(rr[iF]||''));}}

var brows=sh('Read BOUNCES');var bh=(brows[0]||[]).map(function(x){return String(x||'').trim().toLowerCase();});
var bounces=[];for(var b=1;b<brows.length;b++){var br=brows[b]||[];var any=false;for(var c=0;c<br.length;c++)if(String(br[c]||'').trim())any=true;if(!any)continue;var ob={};for(var d=0;d<bh.length;d++)if(bh[d])ob[bh[d]]=String(br[d]||'');bounces.push(ob);}

var srows=sh('Read STARTUPS');var sh2=(srows[0]||[]).map(function(x){return String(x||'').trim().toLowerCase();});
var su=[];for(var e=1;e<srows.length;e++){var sr=srows[e]||[];var any2=false;for(var f=0;f<sr.length;f++)if(String(sr[f]||'').trim())any2=true;if(!any2)continue;var os={};for(var g=0;g<sh2.length;g++)if(sh2[g])os[sh2[g]]=String(sr[g]||'');su.push(os);}

return [{json:{tabs:tabs,onboardingHeader:hdr,cols:C,statusCount:statusCount,subjectPatterns:subjPat,onboardingRows:onb.length,investorsRows:irows.length,investorsHeaderHasDnc:iD,dncCount:dnc.length,dnc:dnc,bouncesHeader:bh,bouncesRows:bounces.length,bounces:bounces,startupsHeader:sh2,startupsRows:su.length,onb:onb,startups:su}}];

